let settingsArea='conversation';
let section='rules',memoryFilter='work',query='',current=null,initial='',initialExpiry='',toastTimer,confirmAction;
let metrics={human:70,auto:90,score:75};
const content=$('#settings-content');
const button=(id,label,primary=false)=>`<button id="${id}" class="material ${primary?'primary':''}" type="button"><span class="lg-content">${label}</span></button>`;
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function pendingMemoryCount(){return records.filter(r=>r.kind==='memory'&&r.status==='candidate').length;}
function attachSegments(host,value,onChange){const api=mountSegmented(host,{value,trackRim:false,liftPx:2,glass:{theme:'light',lightAngle:225,reflection:1},onChange});materials.set(host,api);return api;}
function renderLinks(){const data=settingsArea==='general'?[['metrics','sliders','OCR 与评分']]:[['rules','rules','个人指令'],['memory','memory','记忆与事项']];$('.settings-nav h1').textContent=settingsArea==='general'?'主设置':'会话设置';$('.nav-note').hidden=true;const nav=$('#settings-links');if(nav.dataset.area!==settingsArea){disposeWithin(nav);nav.dataset.area=settingsArea;nav.innerHTML=`<div class="settings-directory">${data.map(([id,i,label])=>`<button class="settings-link" data-section="${id}">${icon(i)}<span>${label}</span></button>`).join('')}</div><div class="settings-compact"><div id="settings-segments" aria-label="会话设置分类">${data.map(([id,,label])=>`<button data-value="${id}">${label}</button>`).join('')}</div></div>`;const change=value=>{section=value;query='';renderSettings();};nav.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>change(b.dataset.section));if(data.length>1)attachSegments($('#settings-segments'),section,change);else $('#settings-segments').classList.add('single-section');}nav.querySelectorAll('[data-section]').forEach(b=>{if(b.dataset.section===section)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});materials.get($('#settings-segments'))?.select(section,{notify:false});content.setAttribute('aria-label',data.find(([id])=>id===section)?.[2]??'会话设置');}
function capabilityDisclosure(){return `<details class="disclosure capability-disclosure"><summary>能力与权限</summary><dl class="parameter-list"><dt>可查询</dt><dd>可访问班级、名单、课表、课堂任务、座位、提醒及部分学生记录。</dd><dt>尚未开放</dt><dd>正式助手的教学业务写入、资料检索和批改结果查询。</dd><dt>控制范围</dt><dd>学生主体及身份由教师手动维护。个人指令按本人跨会话使用，不改变工具权限。</dd></dl></details>`;}
function rows(){const selected=records.filter(r=>r.kind===section&&r.status!=='deleted'&&(section!=='memory'||(memoryFilter==='pending'?r.status==='candidate':r.status!=='candidate'))&&r.content.includes(query));return selected.length?selected.map(r=>`<button class="record-row" data-record="${r.id}" aria-label="查看${esc(r.content)}"><span class="row-copy"><span class="row-title">${esc(r.content)}</span><span class="row-subtitle"><span class="row-status ${r.status==='candidate'?'pending':''}">${{active:'已启用',disabled:'已停用',candidate:'待确认'}[r.status]}</span><span>${r.updated}${r.source==='本人添加'?' · 本人添加':''}</span></span></span>${icon('chevron')}</button>`).join(''):'<p class="empty">没有符合条件的记录。</p>';}
function wireRows(){content.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openEntry(records.find(r=>r.id===Number(b.dataset.record))));}
function renderSettings(){disposeWithin(content);renderLinks();if(section==='metrics')renderMetrics();else if(section==='memory')renderMemory();else renderPrompt();if(settingsArea==='conversation')content.insertAdjacentHTML('beforeend',capabilityDisclosure());hydrate(content);}
let promptDraft='# 交流方式\n\n回答简洁，使用中文。\n不确定的学生情况先查记录。\n\n# 教学安排\n\n教案先列教学目标，再列教学过程。\n课堂活动给出具体的教师提问，优先考虑四十分钟内能完成的安排。';
let promptSaved=promptDraft;
let promptEditing=false;
function renderPrompt(){content.innerHTML=`<section class="prompt-document ${promptEditing?'is-editing':'is-reading'}"><div class="document-toolbar"><span class="document-name">个人指令.md</span><div><span id="prompt-status" role="status">${promptEditing?(promptDraft===promptSaved?'编辑中':'未保存'):''}</span>${promptEditing?button('cancel-prompt','取消')+button('save-prompt','保存',true):button('copy-prompt','复制')+button('edit-prompt','编辑',true)}</div></div>${promptEditing?`<label class="sr-only" for="prompt-markdown">个人指令 Markdown 原文</label><textarea id="prompt-markdown" spellcheck="false" maxlength="16000">${esc(promptDraft)}</textarea>`:`<pre class="prompt-reading" tabindex="0" aria-label="个人指令 Markdown 内容">${esc(promptSaved)}</pre>`}<div class="document-footer"><span>Markdown</span><span>本人 · 跨会话</span></div></section>`;if(!promptEditing){$('#edit-prompt').onclick=()=>{promptDraft=promptSaved;promptEditing=true;renderSettings();$('#prompt-markdown').focus();};$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(promptSaved);toast('已复制个人指令。');}catch{toast('复制未完成，请选中文本后手动复制。');}};return;}$('#prompt-markdown').oninput=e=>{promptDraft=e.target.value;$('#prompt-status').textContent=promptDraft===promptSaved?'编辑中':'未保存';};$('#save-prompt').onclick=()=>{promptSaved=promptDraft;promptEditing=false;renderSettings();toast('已保存演示草稿，未改变正式助手指令。');};$('#cancel-prompt').onclick=()=>{const discard=()=>{promptDraft=promptSaved;promptEditing=false;renderSettings();};if(promptDraft!==promptSaved)confirm('放弃未保存的修改？','本次编辑尚未保存。',discard,'放弃修改');else discard();};$('#prompt-markdown').onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('#save-prompt').click();}};}
function renderMemory(){content.innerHTML=`<div class="memory-toolbar"><div class="segment-wrap"><div id="memory-segments"><button data-value="work">协作事项</button><button data-value="saved">长期背景</button><button data-value="pending">待确认${pendingMemoryCount()?` · ${pendingMemoryCount()}`:''}</button></div></div><div id="memory-actions"></div></div><div id="memory-body"></div>`;const host=$('#memory-segments');attachSegments(host,memoryFilter,value=>{memoryFilter=value;query='';selectedWork=null;renderMemoryBody();});renderMemoryBody();}
function renderMemoryBody(){const body=$('#memory-body'),actions=$('#memory-actions');disposeWithin(body);disposeWithin(actions);actions.innerHTML=memoryFilter==='saved'?button('new-entry',icon('plus')+'新增',true):'';if($('#new-entry'))$('#new-entry').onclick=()=>openEntry(null);if(memoryFilter==='work')renderWork();else{body.innerHTML=(memoryFilter==='saved'?`<label class="search memory-search">${icon('search')}<input id="search-memory" type="search" aria-label="搜索长期背景" placeholder="搜索长期背景" value="${esc(query)}"></label>`:'')+`<div class="row-list" id="memory-list">${rows()}</div>`;if($('#search-memory'))$('#search-memory').oninput=e=>{query=e.target.value;$('#memory-list').innerHTML=rows();wireRows();};wireRows();}hydrate(actions);hydrate(body);}
function control(key,title,value,min,max,step=1){return `<div class="metric-control ${key==='score'?'solo':''}"><label for="metric-${key}">${title}<output id="output-${key}" for="metric-${key}">${value}<small>%</small></output></label><input id="metric-${key}" type="range" value="${value}" min="${min}" max="${max}" step="${step}"></div>`;}
function renderMetrics(){content.innerHTML=`<section class="metric-group"><h3>图像与 OCR 质检</h3><div class="metric-controls">${control('human','人工复核阈值',metrics.human,50,80,5)}${control('auto','自动通过阈值',metrics.auto,75,98)}</div></section><section class="metric-group"><h3>AI 评分置信度</h3><div class="metric-controls">${control('score','评分置信度阈值',metrics.score,50,95,5)}</div></section><div class="metric-actions">${button('save-metrics','保存设置',true)}</div><p class="footnote">当前正式页面使用固定默认值；这些调节尚未完整接通判定流程。此处只模拟保存，不改变真实批改。</p><details class="disclosure"><summary>指标含义与生效范围</summary><p>人工复核与自动通过阈值：拟用于 OCR 质量分流，需先验证质量分数的定义及其与真实错误的关系。</p><p>评分置信度阈值：拟用于标记需教师核对的结果；不应将模型自评直接当作准确率。</p><p>正式接入前需确定参数存储、对哪些新任务生效，以及判定服务的实际消费位置。未接入前不显示“全局已生效”。</p></details>`;
 for(const key of ['human','auto','score'])$('#metric-'+key).oninput=e=>{let value=Number(e.target.value);if(key==='human')value=Math.min(value,Number($('#metric-auto').value)-5);if(key==='auto')value=Math.max(value,Number($('#metric-human').value)+5);e.target.value=value;$('#output-'+key).innerHTML=value+'<small>%</small>';};
 $('#save-metrics').onclick=()=>{for(const key of ['human','auto','score'])metrics[key]=Number($('#metric-'+key).value);toast('演示：阈值已保存，未改变真实批改设置。');};}
function confirm(title,body,action,label='确认'){$('#confirm-title').textContent=title;$('#confirm-body').textContent=body;$('#confirm-yes .lg-content').textContent=label;confirmAction=action;$('#confirm-dialog').showModal();}
function dirty(){return $('#entry-content').value!==initial||$('#entry-expiry').value!==initialExpiry;}
function closeEntry(){if(dirty())confirm('放弃未保存的修改？','本次填写尚未保存。',()=>$('#entry-dialog').close(),'放弃修改');else $('#entry-dialog').close();}
function openEntry(record){current=record;initial=record?.content??'';initialExpiry=record?.expiry??'';const kind=record?.kind??section;const pending=record?.status==='candidate';$('#dialog-category').textContent=kind==='rules'?'个人规则':'长期记忆';$('#dialog-title').textContent=pending?'确认这条记忆':record?'编辑内容':kind==='rules'?'新增个人规则':'新增记忆';$('#content-label').textContent=pending?'拟保存的内容':'内容';$('#entry-content').value=initial;$('#entry-content').placeholder=kind==='rules'?'例如：教案先列教学目标，再列教学过程。':'例如：这学期重点改善课堂讨论参与度。';$('#entry-expiry').value=initialExpiry;$('#entry-meta').textContent=pending?'确认前，你可以先调整这段内容。':record?'当前'+(record.status==='active'?'已启用':'已停用')+' · 更新于'+record.updated:'保存后用于后续助手请求。';$('#entry-source').textContent='来源：'+(record?.source??'本人添加');$('#save-entry .lg-content').textContent=pending?'确认保存':record?'保存修改':'保存';$('#more-entry').hidden=!record;$('#more-menu').hidden=true;$('#more-entry').setAttribute('aria-expanded','false');$('#toggle-entry').textContent=pending?'暂不保存':record?.status==='disabled'?'启用这条记录':'停用这条记录';$('#history-panel').hidden=true;$('#entry-dialog').querySelector('details').open=pending;$('#entry-dialog').showModal();hydrate($('#entry-dialog'));}
$('#entry-form').onsubmit=e=>{e.preventDefault();const text=$('#entry-content').value.trim();if(!text){$('#entry-content').focus();return;}const pending=current?.status==='candidate';if(current){current.content=text;current.expiry=$('#entry-expiry').value;current.updated='刚刚';if(pending)current.status='active';}else records.push({id:Date.now(),kind:section,content:text,expiry:$('#entry-expiry').value,status:'active',updated:'刚刚',source:'本人添加'});$('#entry-dialog').close();renderSettings();toast(pending?'演示：记忆已确认保存。':'演示：已保存，未改动真实记录。');};
$('#close-entry').onclick=closeEntry;$('#entry-dialog').oncancel=e=>{e.preventDefault();closeEntry();};
$('#more-entry').onclick=()=>{$('#more-menu').hidden=!$('#more-menu').hidden;$('#more-entry').setAttribute('aria-expanded',String(!$('#more-menu').hidden));};
$('#history-entry').onclick=()=>{$('#history-panel').hidden=false;$('#history-panel').textContent='修改记录示例：今天保存当前内容。实际应用中将在这里查看历史版本和原始来源。';$('#more-menu').hidden=true;};
$('#toggle-entry').onclick=()=>{if(dirty()){toast('请先保存或取消当前修改。');return;}if(current.status==='candidate'){confirm('暂不保存这条记忆？','这条建议不会作为长期记忆使用。',()=>{current.status='deleted';$('#entry-dialog').close();renderSettings();toast('演示：已忽略这条建议。');},'暂不保存');return;}current.status=current.status==='active'?'disabled':'active';$('#entry-dialog').close();renderSettings();toast('演示：已'+(current.status==='active'?'启用':'停用')+'。');};
$('#delete-entry').onclick=()=>confirm('删除这条记录？','后续不再召回这条内容，原对话和历史版本仍保留。',()=>{current.status='deleted';$('#entry-dialog').close();renderSettings();toast('演示：记录已删除。');},'删除');
$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();$('#confirm-yes').onclick=()=>{$('#confirm-dialog').close();confirmAction?.();};
function scene(name){const chat=name==='chat';if(!chat){settingsArea=name==='general'?'general':'conversation';if(settingsArea==='general')section='metrics';else if(section==='metrics')section='rules';renderSettings();}$('#settings-scene').hidden=chat;$('#chat-scene').hidden=!chat;$('#breadcrumb').textContent=chat?'工作台 / AI 助手':settingsArea==='general'?'主设置 / OCR 与评分':'AI 助手 / 会话设置';$('#return-chat').hidden=chat;document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===name)));}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>scene(b.dataset.scene));$('#return-chat').onclick=()=>scene('chat');$('#sidebar-settings').onclick=()=>{section='rules';renderSettings();scene('settings');};
