let selectedWork=null;
function renderWork(){const body=$('#memory-body');body.innerHTML=selectedWork?`<section class="work-detail"><button id="back-work" class="text-button">‹ 返回事项</button><span class="status-pill">${selectedWork.state}</span><h3>${selectedWork.title}</h3><p>${selectedWork.detail}</p><dl><dt>关联记录</dt><dd>${selectedWork.ref}</dd><dt>上次约定</dt><dd>${selectedWork.next}</dd><dt>来源</dt><dd>${selectedWork.source}</dd></dl>${button('resume-work','继续这件事',true)}</section>`:`<div class="row-list">${workItems.map(w=>`<button class="record-row" data-work="${w.id}"><span class="row-copy"><span class="row-title">${w.title}</span><span class="row-subtitle"><span class="row-status">${w.state}</span><span>${w.source}</span></span><span class="work-next">${w.next}</span></span>${icon('chevron')}</button>`).join('')}</div>`;body.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>{selectedWork=workItems.find(w=>w.id===b.dataset.work);renderMemoryBody();});if($('#back-work'))$('#back-work').onclick=()=>{selectedWork=null;renderMemoryBody();};if($('#resume-work'))$('#resume-work').onclick=()=>{const follow=selectedWork.id==='follow';scene('chat');switchDemo(follow?'follow':'discussion',true);collapse(true);if(follow){$('#chat-draft').value='继续跟进小林的作业补交，先核对现在的记录。';demoSessions.follow.draft=$('#chat-draft').value;}else{$('#chat-draft').value='继续讨论方案，先确定课文和分组方式。';demoSessions.discussion.draft=$('#chat-draft').value;}$('#chat-draft').focus();};}
